#!/usr/bin/env bash
# One-command setup and verification for the Python course.
#   scripts/setup.sh           check Python, verify files, run Day 1 + Day 2 smoke checks
#   scripts/setup.sh --day1    check Python and verify Day 1 only
#   scripts/setup.sh --day2    check Python and verify Day 2 only
#   scripts/setup.sh --reset   remove temporary File I/O outputs generated by demos
#
# Exit codes: 0 ok | 10 python3 missing | 11 python < 3.10 | 12 missing course files | 13 smoke test failed
set -u
cd "$(dirname "$0")/.."

say()  { printf '%s\n' "$*"; }
step() { printf '\n== %s\n' "$*"; }

MODE="all"
case "${1:-}" in
  --day1)  MODE="day1" ;;
  --day2)  MODE="day2" ;;
  --reset)
    step "Resetting generated demo output files"
    rm -f demos/day2/data/run_log.txt demos/day2/data/updated_config.json
    say "Demo workspace cleaned."
    exit 0
    ;;
  "") ;;
  *)
    say "Usage: scripts/setup.sh [--day1 | --day2 | --reset]"
    exit 12
    ;;
esac

step "Checking Python prerequisite"
if ! command -v python3 >/dev/null 2>&1; then
  say "ERROR: python3 not found. Install Python 3.10+ from https://www.python.org/downloads/"
  exit 10
fi

PY_VER=$(python3 -c 'import sys; print(f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}")')
if ! python3 -c 'import sys; raise SystemExit(0 if sys.version_info >= (3, 10) else 1)'; then
  say "ERROR: Python $PY_VER found, but Python 3.10 or newer is required."
  exit 11
fi
say "python3 $PY_VER ok"

step "Checking required course files"
REQUIRED=(
  "README.md"
  "docs/course-toc.md"
  "course/modules/01-python-i.md"
  "course/modules/02-python-ii.md"
  "course/slides/day1-python-i-slides.md"
  "course/slides/day2-python-ii-slides.md"
  "demos/day1/beat_1_1_variables.py"
  "demos/day2/beat_2_1_functions.py"
  "demos/day2/data/model_config.json"
  "demos/day2/data/prompt_docs.txt"
  "exercises/day1_exercise.py"
  "exercises/day2_exercise.py"
)
for f in "${REQUIRED[@]}"; do
  if [ ! -f "$f" ]; then
    say "ERROR: missing required file: $f"
    exit 12
  fi
done
say "all core course files present"

step "Running smoke checks ($MODE)"
if bash scripts/smoke.sh "$MODE"; then
  step "READY"
  say "Day 1 Module: course/modules/01-python-i.md  (Slides: course/slides/day1-python-i-slides.md)"
  say "Day 2 Module: course/modules/02-python-ii.md (Slides: course/slides/day2-python-ii-slides.md)"
  say "Unit Tests:   python3 -m unittest discover -s exercises/tests -v"
  say "Reset demos:  scripts/setup.sh --reset"
  exit 0
fi

say "ERROR: smoke test failed. Review FAIL lines above."
exit 13

